                ['Cushman & Wakefield', '1,789 MW', 'H1 2026', 'Top seven cities, colocation plus hyperscale cloud, excludes captive'],
                ['Savills', '1,819 MW IT', 'H1 2026', 'All segments including edge and enterprise'],
                ['Anarock', 'More than 1.8 GW', 'H1 2026', 'Not stated'],
                ['CBRE', '2 GW expected', 'End-2026', 'Not stated'],
